CREATE TABLE "StaticPageContent" (
    "id" TEXT NOT NULL,
    "path" TEXT NOT NULL,
    "blocks" JSONB NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "StaticPageContent_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "StaticPageContent_path_key" ON "StaticPageContent"("path");
CREATE INDEX "StaticPageContent_path_idx" ON "StaticPageContent"("path");

-- Seed the current storefront pages so enabling the builder never produces empty pages.
